;
;
; syscall1
;
;   INPUT: (a, int)
;   OUTPUT: (int)
func.30: ; syscall1
    push    rbp                        ; save return address
    mov     rbp, rsp                   ; set up stack frame
    sub     rsp, 32                    ; allocate 4 local variables

    ; t0 <- int
    call    stack_pop
    mov     qword [rbp - loc_0], rax

    ; t1 <- a
    call    stack_pop
    mov     qword [rbp - loc_1], rax

    ; syscall1(t0) t1
    mov     rax, qword [rbp - loc_0]
    mov     rdi, qword [rbp - loc_1]
    syscall

    mov     rdi, rax
    call    stack_push

    add     rsp, 32                    ; deallocate local variables
    pop     rbp                        ; restore return address
    ret

;
;
; syscall3
;
;   INPUT: (a, b, c, int)
;   OUTPUT: (int)
func.31: ; syscall3
    push    rbp                        ; save return address
    mov     rbp, rsp                   ; set up stack frame
    sub     rsp, 32                    ; allocate 4 local variables

    ; t0 <- int
    call    stack_pop
    mov     qword [rbp - loc_0], rax

    ; t1 <- c
    call    stack_pop
    mov     qword [rbp - loc_1], rax

    ; t2 <- b
    call    stack_pop
    mov     qword [rbp - loc_2], rax

    ; t3 <- a
    call    stack_pop
    mov     qword [rbp - loc_3], rax

    ; syscall3(t0) t3 t2 t1
    mov     rax, qword [rbp - loc_0]
    mov     rdi, qword [rbp - loc_3]
    mov     rsi, qword [rbp - loc_2]
    mov     rdx, qword [rbp - loc_1]
    syscall

    mov     rdi, rax
    call    stack_push

    add     rsp, 32                    ; deallocate local variables
    pop     rbp                        ; restore return address
    ret

section '.text' executable

func.32: ; stack_token_kind.map
    push    rbp
    mov     rbp, rsp

    call    func.1 ; dup
    mov     rdi, literal.0 ; 0
    call    stack_push_addr
    call    func.19 ; =
    call    stack_pop
    test    rax, rax
    jnz     .if0
.else0:
    call    func.1 ; dup
    mov     rdi, literal.1 ; 1
    call    stack_push_addr
    call    func.19 ; =
    call    stack_pop
    test    rax, rax
    jnz     .if1
